def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product that can be obtained by inserting K multiplication
    signs into the number string ``num_str`` of length N.
    """
    # Basic validation
    if len(num_str) != N:
        raise ValueError("Length of num_str does not match N")
    if K < 0 or K > N - 1:
        raise ValueError("K must be between 0 and N-1 inclusive")

    # Special case: no multiplication signs
    if K == 0:
        return int(num_str)

    # Precompute integer values for all substrings [i:j] (0-indexed, exclusive j)
    values = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        num = 0
        for j in range(i + 1, N + 1):
            num = num * 10 + (ord(num_str[j - 1]) - 48)  # faster than int()
            values[i][j] = num

    # dp[i][k] = maximum product for the first i digits with exactly k cuts
    dp = [[None] * (K + 1) for _ in range(N + 1)]

    # Base case: no cuts – take the whole prefix as a single number
    for i in range(1, N + 1):
        dp[i][0] = values[0][i]

    # Fill DP
    for i in range(1, N + 1):
        # maximum possible cuts for prefix of length i is min(K, i-1)
        max_k = min(K, i - 1)
        for k in range(1, max_k + 1):
            best = None
            # The last segment starts at position j (0-indexed), so that prefix j has k-1 cuts
            # j must be at least k so each segment is non-empty
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev is None:
                    continue
                val = prev * values[j][i]
                if best is None or val > best:
                    best = val
            dp[i][k] = best

    result = dp[N][K]
    if result is None:
        # This should not happen for valid inputs
        return 0
    return result

