def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Uses breadth-first search (BFS) to explore all possible transformations.

    Parameters:
        n (int): The original integer number to transform.
        rules (list[tuple[int, int]]): Source/destination digit transformations.

    Returns:
        int: The total count of unique numbers that can be generated, including the original number.
    """
    if n < 0:
        raise ValueError("Only non‑negative integers are supported.")

    # Build a mapping from source digit to a list of possible destination digits.
    mapping = {}
    for src, dst in rules:
        key = str(src)
        mapping.setdefault(key, []).append(str(dst))

    start = str(n)
    visited = {int(start)}
    queue = [start]

    from collections import deque
    queue = deque(queue)

    while queue:
        current = queue.popleft()
        # Try transforming each digit where a rule exists.
        for idx, digit in enumerate(current):
            if digit in mapping:
                for replacement in mapping[digit]:
                    new_num_str = current[:idx] + replacement + current[idx+1:]
                    new_num = int(new_num_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num_str)

    return len(visited)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) explores all possible transformations. The function returns the count of unique
    numbers that can be generated from the original number, including the number itself.

    Parameters:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
      as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    # Basic input validation
    if not isinstance(n, int) or n < 0:
        raise ValueError("The number 'n' must be a non-negative integer.")
    if not isinstance(rules, list):
        raise ValueError("The 'rules' must be a list of tuples.")
    # Build a mapping from digit to a list of possible replacements
    rule_map = {}
    for rule in rules:
        if (
            not isinstance(rule, tuple)
            or len(rule) != 2
            or not all(isinstance(x, int) and 0 <= x <= 9 for x in rule)
        ):
            raise ValueError(f"Invalid rule format: {rule}. Each rule must be a tuple of two digits between 0 and 9.")
        x, y = rule
        rule_map.setdefault(x, []).append(y)

    start_str = str(n)
    visited = {n}
    queue = [start_str]

    while queue:
        current = queue.pop(0)
        digits = list(current)
        for idx, ch in enumerate(digits):
            d = int(ch)
            if d not in rule_map:
                continue
            for replacement in rule_map[d]:
                new_digits = digits.copy()
                new_digits[idx] = str(replacement)
                new_number_str = "".join(new_digits)
                try:
                    new_number = int(new_number_str)
                except ValueError:
                    # Skip invalid number strings (should not happen)
                    continue
                if new_number not in visited:
                    visited.add(new_number)
                    queue.append(new_number_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize inputs
    scenario = scenario.upper()
    liar_count = {name.upper() for name in liar_count}
    participants = {name.upper() for name in statements.keys()}
    days_of_week = {day.upper() for day in days_of_week}

    def is_ignored(statement: str) -> bool:
        """Return True if the statement contains a day of the week."""
        lowered = statement.upper()
        return any(day in lowered for day in days_of_week)

    def evaluate_statement(statement: str, speaker: str) -> bool | None:
        """Return True if statement is true, False if false, None if not evaluatable."""
        stmt = statement.strip()
        if not stmt:
            return None
        if is_ignored(stmt):
            return None
        stmt_lower = stmt.lower()

        # Only consider statements that mention guilt.
        if "guilty" not in stmt_lower:
            return None

        # Determine if statement claims guilty or not guilty
        is_guilty_claim = "not guilty" not in stmt_lower  # truth if not mentioning 'not guilty'
        # Determine subject of the statement.
        subject = None
        # Check for self reference
        if stmt_lower.startswith(("i ", "i'm", "I'm")):
            subject = speaker
        else:
            # Look for any participant name in the statement (case-insensitive)
            for name in participants:
                # Use word boundaries to avoid partial matches
                if f" {name.lower()} " in f" {stmt_lower} ":
                    subject = name
                    break
                if stmt_lower.startswith(name.lower() + " "):
                    subject = name
                    break
                if stmt_lower.endswith(" " + name.lower() + ".") or stmt_lower.endswith(" " + name.lower() + ","):
                    subject = name
                    break

        if subject is None:
            # Unable to determine subject; ignore
            return None

        # Evaluate truth based on scenario
        if subject == scenario:
            # Claim about the scenario's guilt status
            return is_guilty_claim
        else:
            # Claim about another participant
            return not is_guilty_claim

    for speaker_raw, stmts in statements.items():
        speaker = speaker_raw.upper()
        for stmt in stmts:
            truth_value = evaluate_statement(stmt, speaker)
            if truth_value is None:
                continue  # Not evaluatable
            # Check consistency with liar assumption
            if speaker in liar_count:
                # Liars must make false statements
                if truth_value:
                    return False
            else:
                # Truth-tellers must make true statements
                if not truth_value:
                    return False
    return True

