def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    def is_day_statement(statement: str) -> bool:
        """Return True if any day of the week appears in the statement (case‑insensitive)."""
        statement_lower = statement.lower()
        return any(day.lower() in statement_lower for day in days_of_week)

    def truth_of(statement: str, speaker: str) -> bool | None:
        """Evaluate the truth value of a statement given the scenario.

        Returns:
            True if the statement is true,
            False if the statement is false,
            None if the statement does not match a recognized pattern.
        """
        s = statement.strip().rstrip('.').lower()
        # Speaker refers to themselves
        if s == "i am guilty":
            return speaker.lower() == scenario.lower()
        if s == "i am not guilty":
            return speaker.lower() != scenario.lower()

        # Statements about other participants
        m_guilty = re.fullmatch(r"(\w+)\s+is\s+guilty", s)
        if m_guilty:
            name = m_guilty.group(1)
            return name.lower() == scenario.lower()

        m_not = re.fullmatch(r"(\w+)\s+is\s+not\s+guilty", s)
        if m_not:
            name = m_not.group(1)
            return name.lower() != scenario.lower()

        # Unrecognised statement format
        return None

    for participant, stmt_list in statements.items():
        for stmt in stmt_list:
            if is_day_statement(stmt):
                continue  # ignore day‑of‑week statements

            truth_value = truth_of(stmt, participant)
            if truth_value is None:
                continue  # ignore statements that don't fit expected patterns

            # If the participant is a liar, their statements must be false
            if participant in liar_count:
                if truth_value:  # statement should be false
                    return False
            else:
                if not truth_value:  # truthful participant said something false
                    return False

    return True

def catalan_number(n: int) -> int:
    """Compute the nth Catalan number using dynamic programming."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for k in range(i):
            total += catalan[k] * catalan[i - 1 - k]
        catalan[i] = total
    return catalan[n]

def calculate_arrangements(n, m, a) -> int:
    """
    Compute the number of ways to arrange m pots of flowers using up to n types,
    where the ith type can have at most a[i] pots, and the arrangement must be in
    increasing order of flower types.

    Args:
    - n (int): The number of flower types available.
    - m (int): The total number of flower pots to arrange.
    - a (list of int): A list where a[i] is the maximum number of pots for the ith type of flower.

    Returns:
    - int: The number of distinct arrangements modulo (10^6 + 7).
    """
    MOD = 1000007
    try:
        if not isinstance(n, int) or not isinstance(m, int) or not isinstance(a, list):
            return 0
        if n != len(a) or m < 0:
            return 0
        if any(not isinstance(x, int) or x < 0 for x in a):
            return 0
        if m == 0:
            return 1
        if sum(a) < m:
            return 0

        dp = [0] * (m + 1)
        dp[0] = 1

        for limit in a:
            pref = [0] * (m + 1)
            pref[0] = dp[0]
            for i in range(1, m + 1):
                pref[i] = (pref[i - 1] + dp[i]) % MOD

            new_dp = [0] * (m + 1)
            for k in range(m + 1):
                lo = k - limit
                if lo > 0:
                    val = pref[k] - pref[lo - 1]
                else:
                    val = pref[k]
                new_dp[k] = val % MOD

            dp = new_dp
        return dp[m] % MOD
    except Exception:
        return 0

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is a strictly increasing sequence followed by a strictly decreasing sequence.
    The function returns the minimal deletions required to achieve such a sequence.

    :param heights: List[int] - heights of the students in the current order.
    :return: int - minimum number of students that need to leave.
    """
    # Input validation
    if not isinstance(heights, list):
        raise ValueError("heights must be a list")
    if len(heights) == 0:
        return 0
    for h in heights:
        if not isinstance(h, int):
            raise ValueError("heights must contain integers")

    n = len(heights)

    # Longest increasing subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find the maximum length of a bitonic subsequence
    max_len = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1  # peak counted twice, subtract 1
        if bitonic_len > max_len:
            max_len = bitonic_len

    # Minimum deletions needed
    return n - max_len

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    A choir formation is defined such that for some position 'i',
    the heights of students increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 2:
        return 0

    # Longest Increasing Subsequence (LIS) ending at each position
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest Decreasing Subsequence (LDS) starting at each position
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find the maximum length of a bitonic subsequence
    max_len = 0
    for i in range(n):
        current = lis[i] + lds[i] - 1
        if current > max_len:
            max_len = current

    return n - max_len
